<template><div class="ky-page" v-loading="loading"><div class="ky-page-header"><h2 class="ky-page-title">个体阈值审核</h2><el-select v-model="status" @change="load"><el-option label="待审核" value="PENDING" /><el-option label="已通过" value="APPROVED" /><el-option label="已驳回" value="REJECTED" /></el-select><el-button @click="load">刷新申请</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><div class="ky-card"><el-table :data="rows"><el-table-column prop="elder_name" label="老人" /><el-table-column prop="indicator_name" label="指标" /><el-table-column prop="reason" label="申请依据" min-width="180" /><el-table-column label="申请内容" min-width="220"><template #default="{row}"><span v-if="row.restore_default">恢复院内默认</span><template v-else><div v-for="n in [0,1,2,3]" :key="n">{{ n===0?'正常':'风险'+n+'级' }}：{{ row['level'+n+'_range'] || row.rules?.['level'+n] || row.ranges?.['level'+n] || '见详情' }}</div></template></template></el-table-column><el-table-column prop="proposer_name" label="申请人" /><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='PENDING'" type="primary" link @click="current=row;note='';dialog=true">审核</el-button><span v-else>{{ row.review_note || row.note }}</span></template></el-table-column></el-table><el-empty v-if="!rows.length" description="暂无此状态的个体阈值申请" /></div><el-dialog v-model="dialog" title="审核个体健康阈值" width="min(600px,95vw)"><p>{{ current?.elder_name }} · {{ current?.indicator }}</p><p>申请依据：{{ current?.reason }}</p><el-alert type="warning" :closable="false" title="请依据实际医护确认记录审核，系统不会让 AI 自动修改健康阈值。" /><el-input v-model="note" type="textarea" :rows="3" maxlength="500" placeholder="填写审核依据或驳回原因（必填）" style="margin-top:16px" /><template #footer><el-button :loading="saving" @click="review(false)">驳回并留痕</el-button><el-button type="primary" :loading="saving" @click="review(true)">通过并生效</el-button></template></el-dialog></div></template>
<script setup>
import { ref,onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import { listThresholdProposals,reviewThresholdProposal } from '@/api'
const rows=ref([]),status=ref('PENDING'),loading=ref(false),saving=ref(false),error=ref(''),dialog=ref(false),current=ref(null),note=ref('')
async function load(){loading.value=true;error.value='';try{rows.value=await listThresholdProposals({status:status.value})}catch(e){error.value=e.message}finally{loading.value=false}}
async function review(approve){if(!note.value.trim())return ElMessage.warning('请填写审核依据或驳回原因');saving.value=true;try{await reviewThresholdProposal(current.value.proposal_id || current.value.id,{approve,note:note.value});dialog.value=false;await load();ElMessage.success(approve?'个体阈值已审核生效':'申请已驳回并保留记录')}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
onMounted(load)
</script>
